    "answer": "1长太息以掩涕兮     哀民生之多艰     2余虽好修姱以羁兮     謇朝谇而夕替     3既替余以蕙纕兮     又申之以揽茝     4亦余心之所善兮     虽九死其犹未悔     5怨灵修之浩荡兮     终不察夫民心     6众女嫉余之蛾眉兮     谣诼谓余以善淫     7固时俗之工巧兮     偭规矩而改错     8背绳墨以追曲兮     竞周容以为度     9忳郁邑余侘傺兮     吾独穷困乎此时也     10宁溘死以流亡兮     余不忍为此态也     11鸷鸟之不群兮     自前世而固然     12何方圜之能周兮     夫孰异道而相安     13何方圜之能周兮     夫孰异道而相安     14宁溘死以流亡兮     余不忍为此态也     15屈心而抑志兮     忍尤而攘诟     16伏清白以死直兮     固前圣之所厚    17悔相道之不察兮     延伫乎吾将反     18回朕车以复路兮     及行迷之未远     19步余马于兰皋兮     驰椒丘且焉止息     20进不入以离尤兮     退将复修吾初服     21制芰荷以为衣兮     集芙蓉以为裳     22不吾知其亦已兮     苟余情其信芳     23高余冠之岌岌兮     长余佩之陆离     24民生各有所乐兮     余独好修以为常     25虽体解吾犹未变兮     岂余心之可惩     26长太息以掩涕兮     哀民生之多艰     27亦余心之所善兮     虽九死其犹未悔"
